    for(int k=0;k<readingEdges.Length;k++){var e=readingEdges[k];float3 original=F(rest[e.b])-F(rest[e.a]);float anchorLength=math.distance(F(anchors[e.b]),F(anchors[e.a]));if(e.ratio<=0){e.ratio=math.distance(F(positions[e.b]),F(positions[e.a]))/math.max(.00001f,anchorLength);readingEdges[k]=e;}float len=anchorLength*e.ratio;if(len<.015f)continue;float strain=(math.distance(F(positions[e.b]),F(positions[e.a]))-len)/len;float sq=math.lengthsq(original),warp=sq<1e-12f?.5f:original.y*original.y/sq;float force=math.lerp(youngWeft,youngWarp,math.saturate(warp))*thickness*strain*(strain<0?compression:1);peakPull=math.max(peakPull,strain);peakPush=math.max(peakPush,-strain);peakTension=math.max(peakTension,force);peakCompression=math.max(peakCompression,-force);float w=len*len;weight+=w;if(strain>0){pull2+=strain*strain*w;tension2+=force*force*w;}else{push2+=strain*strain*w;compression2+=force*force*w;}}
