  public void Dispose(){if(readingEdges.IsCreated)readingEdges.Dispose();if(faceInput.IsCreated)faceInput.Dispose();if(faceProjected.IsCreated)faceProjected.Dispose();if(links.IsCreated)links.Dispose();if(inverseArea.IsCreated)inverseArea.Dispose();if(linkLambda.IsCreated)linkLambda.Dispose();if(rest.IsCreated)rest.Dispose();if(anchors.IsCreated)anchors.Dispose();if(offsets.IsCreated)offsets.Dispose();if(positions.IsCreated)positions.Dispose();if(weights.IsCreated)weights.Dispose();if(triangles.IsCreated)triangles.Dispose();if(bones.IsCreated)bones.Dispose();if(skin.IsCreated)skin.Dispose();if(inverse.IsCreated)inverse.Dispose();if(capsules.IsCreated)capsules.Dispose();if(stats.IsCreated)stats.Dispose();}
